#!/usr/bin/env python3
"""FS3 v185 - honest small craft, clear hulls, controls you can look up.

    Small craft   Every fighter and bomber, the player's and the AI's, now
                  has its FreeSpace table values (FS2 ships.tbl, FSPort for
                  the FS1 hulls), scaled so the Myrmidon is 100/100. The
                  same hull flies the same, whoever flies it. NPC hulls grow
                  with the cycle like the player's, and NPC shields come back
                  at the player's rate. The player's Mara in M78 is "SF Mara
                  (terrans)". M9, M23, M27 and M68 have fewer enemies at once
                  or fewer bombers, after the balance measurement.
    Mission end   Rocks, wreckage and hull sections are no longer pushed off
                  to the left; they drift on and are cleared in the dark of
                  the jump.
    Scenery       An installation that is pure scenery (Arcadia, Knossos)
                  catches no shots any more.
    Subsystems    The hull stays clear. The middle mouse button switches
                  corner brackets on every subsystem on and off.
    Controls      One list of all controls, shown on the title screen and in
                  a new CONTROLS tab of the settings.

Needs v184. Edits src/20_render.js to src/70_ui.js in place, and writes the
updated shipsim.js and fieldsim.js. Run assemble.py afterwards.
"""
import base64
import os
import sys

if "function dmgTrack" not in open("src/20_render.js", encoding="utf-8").read():
    sys.exit("Abbruch: erst v184 einspielen.")
if "SMALL_TBL" in open("src/30_waves.js", encoding="utf-8").read():
    sys.exit("Abbruch: v185 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
rep('src/20_render.js',
    "function bulletOnHull(e, b){\n  if(e && e.ghost) return false;    // shots pass through (M78, v178)\n  if(e.type === 'asteroid') return true;\n  const ea = e.ang || 0;\n  const pr = probeAxis(b);\n  return onHull(e.img, e.x, e.y, e.sc, e.flip, b.x+pr[0], b.y+pr[1], ea)\n",
    "function bulletOnHull(e, b){\n  if(e && e.ghost) return false;    // shots pass through (M78, v178)\n  if(e.type === 'asteroid') return true;\n  // Pure scenery - an installation that cannot be hurt, such as the\n  // Arcadia or the Knossos portal in the background - catches no shots\n  // (v185, Silvio). An installation that is a target is not invuln.\n  if(e.invuln && e.scenery) return false;\n  const ea = e.ang || 0;\n  const pr = probeAxis(b);\n  return onHull(e.img, e.x, e.y, e.sc, e.flip, b.x+pr[0], b.y+pr[1], ea)\n")
